INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 102301, 0, 401, 2, 2, "やったね、ぷうきち！\nこれならお兄ちゃんたちの\nお手本になれたよね！", 24, "アヤネ", "2020/07/31 12:00:00", 10046, 24001, "2030/12/17 14:59:59", 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 102301, 0, 402, 1, 2, "私たちの勝ちだね！\nぷうきちと一緒なら\nどんなボールでも\nホームランを打ってみせるよ！", 24, "アヤネ", "2020/07/31 12:00:00", 10046, 24002, "2030/12/17 14:59:59", 2.21);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 102301, 0, 403, 2, 2, "やったやったぁ！\nお兄ちゃん、見ててくれた？\n私、すっごくがんばったよ！", 24, "アヤネ", "2020/07/31 12:00:00", 10046, 24003, "2030/12/17 14:59:59", 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 192201, 0, 701, 2, 1, "特訓の成果が出たみたいだ！\nもっと練習を重ねて\nこの調子で上達していこう！", 24, "アサヒ", "2020/07/31 12:00:00", 10046, 24004, "2030/12/17 14:59:59", 1.99);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 192201, 0, 702, 1, 2, "よし、いい感じだ！\nキャプテンとしての仕事は\nきっちり果たせそうだよ", 24, "アサヒ", "2020/07/31 12:00:00", 10046, 24005, "2030/12/17 14:59:59", 2.21);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 192201, 0, 703, 2, 1, "試合に向けて\nいい感覚を掴めた気がするよ！\nこのまま一気に全国大会だ！", 24, "アサヒ", "2020/07/31 12:00:00", 10046, 24006, "2030/12/17 14:59:59", 3.33);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 192301, 0, 801, 2, 2, "このくらい余裕だ\nオレたちは全国大会を\n目指してるんだからな", 24, "部員３", "2020/07/31 12:00:00", 10046, 24007, "2030/12/17 14:59:59", 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 192301, 0, 802, 1, 2, "オレだって\nビーチベースボール選手だ\nどんな球だろうが\n全部スタンドまで飛ばしてやる", 24, "部員３", "2020/07/31 12:00:00", 10046, 24008, "2030/12/17 14:59:59", 2.68);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 192301, 0, 803, 2, 2, "いい感じだ\nこれなら試合でも活躍できそうだ\n大暴れしてやる！", 24, "部員３", "2020/07/31 12:00:00", 10046, 24009, "2030/12/17 14:59:59", 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 192501, 0, 501, 1, 1, "やった！", 24, "", "2020/07/31 12:00:00", 10046, 24010, "2030/12/17 14:59:59", 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 192501, 0, 502, 1, 1, "勝ったよ！", 24, "", "2020/07/31 12:00:00", 10046, 24011, "2030/12/17 14:59:59", 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 192501, 0, 503, 1, 1, "いい調子！", 24, "", "2020/07/31 12:00:00", 10046, 24012, "2030/12/17 14:59:59", 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 113501, 0, 111, 6, 2, "あら～…もしかして\n勝っちゃったのかしら？\nみんなの練習を見ていたから\nかもしれないわね", 24, "ミサト", "2020/07/31 12:00:00", 10046, 24013, "2030/12/17 14:59:59", 5.33);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 113501, 0, 112, 1, 2, "みんなの力になりたくて\n先生も頑張ってみました～！\nうまく投げられたみたいで\nよかったわ～！", 24, "ミサト", "2020/07/31 12:00:00", 10046, 24014, "2030/12/17 14:59:59", 6.85);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 113501, 0, 113, 1, 2, "練習お疲れさま～！\n先生も協力できて\nとってもうれしいわ～♪\n次も頑張りましょうね～！", 24, "ミサト", "2020/07/31 12:00:00", 10046, 24015, "2030/12/17 14:59:59", 3);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 192401, 0, 611, 1, 2, "まだ練習が足りねえみてえだな\nこれっぽっちも本気で\n投げてねえっつーの\nもう一回やんぞ！", 24, "ダイチ", "2020/07/31 12:00:00", 10046, 24016, "2030/12/17 14:59:59", 6.11);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 192401, 0, 612, 1, 2, "ふん、当然の結果だな\n俺の球は、誰にも打てねえよ！\nまたやりてえっつーなら\nとことん付き合ってやるぜ！", 24, "ダイチ", "2020/07/31 12:00:00", 10046, 24017, "2030/12/17 14:59:59", 6.75);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 192401, 0, 613, 2, 2, "おっしゃあ！\nこの勢いで全国に行ってやるぜ！\n全員三振で仕留めてやる！", 24, "ダイチ", "2020/07/31 12:00:00", 10046, 24018, "2030/12/17 14:59:59", 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 113401, 0, 211, 2, 1, "きらーん☆\nハツネちゃんの大勝利なのだ～！\nみんながもっと上達できるように\n私もまだまだ頑張るからね！", 24, "ハツネ", "2020/07/31 12:00:00", 10046, 24019, "2030/12/17 14:59:59", 4.52);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 113401, 0, 212, 2, 1, "やったあ！　私の勝ちだね！\nチアリーダーもピッチャーも\nハツネちゃんに任せてよ！", 24, "ハツネ", "2020/07/31 12:00:00", 10046, 24020, "2030/12/17 14:59:59", 3.89);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 113401, 0, 213, 1, 2, "よお～し、この調子でもっと\n頑張ろう…と思ったけど\n超能力を使ったから…\n眠くなってきちゃった…すやぁ…", 24, "ハツネ", "2020/07/31 12:00:00", 10046, 24021, "2030/12/17 14:59:59", 13.49);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 106501, 0, 311, 1, 2, "いい勝負だったぜ！\nたぎっちまって\nつい本気で投げちまったよ", 24, "カヤ", "2020/07/31 12:00:00", 10046, 24022, "2030/12/17 14:59:59", 3.17);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 106501, 0, 312, 1, 2, "どうだ？\nオレ様のボールは熱かっただろ！\nま、でもおまえらの根性も\nなかなかのもんだったぜ", 24, "カヤ", "2020/07/31 12:00:00", 10046, 24023, "2030/12/17 14:59:59", 4.42);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 106501, 0, 313, 6, 1, "なんだよ、そんなもんか？\nこっちはまだまだ投げたりねえ\nもっと勝負しようぜ！", 24, "カヤ", "2020/07/31 12:00:00", 10046, 24024, "2030/12/17 14:59:59", 2.89);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 102301, 0, 421, 4, 3, "あとちょっとだったのに～！\n次こそぷうきちと一緒に\n勝ってみせるからね！", 24, "アヤネ", "2020/07/31 12:00:00", 10046, 24025, "2030/12/17 14:59:59", 3.71);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 192201, 0, 721, 2, 1, "いい勝負だったね！\nでも、やっぱり悔しいな…\nもっと練習して\n今度は絶対に俺が勝つから！", 24, "アサヒ", "2020/07/31 12:00:00", 10046, 24026, "2030/12/17 14:59:59", 5.1);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 192301, 0, 821, 1, 3, "ちっ…あと一歩足りなかったか\n次こそは絶対に勝つから\nそのつもりでいろ", 24, "部員３", "2020/07/31 12:00:00", 10046, 24027, "2030/12/17 14:59:59", 4.34);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 192501, 0, 521, 1, 1, "いい勝負だったよ\nまたやろうね", 24, "", "2020/07/31 12:00:00", 10046, 24028, "2030/12/17 14:59:59", 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 113501, -360, 101, 1, 2, "とってもよくできました～♪\n頑張ってくれて先生うれしいわ\nこれからも試合に向けて\n練習していきましょうね～", 24, "ミサト", "2020/07/31 12:00:00", 10046, 24029, "2030/12/17 14:59:59", 5.62);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 113501, -360, 102, 1, 2, "頑張った成果ね～！\nこのまま練習を続ければ\nもっとすごい成績を残せそうよ\n期待してますからね～！", 24, "ミサト", "2020/07/31 12:00:00", 10046, 24030, "2030/12/17 14:59:59", 9.58);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 113501, -360, 103, 2, 2, "いい子、いい子～♪\n頑張り屋さんのあなたを\nたっくさん褒めてあげますからね", 24, "ミサト", "2020/07/31 12:00:00", 10046, 24031, "2030/12/17 14:59:59", 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 113501, -360, 104, 2, 1, "夢に向けて、一歩前進できたわね\nこの調子で、夢を叶えましょう\n目指せ、全国大会～！", 24, "ミサト", "2020/07/31 12:00:00", 10046, 24032, "2030/12/17 14:59:59", 9.13);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 113501, -360, 105, 1, 2, "絶好調ね～♪\nきっと試合でも大活躍\n間違いなしだわ\n楽しみにしていますからね～！", 24, "ミサト", "2020/07/31 12:00:00", 10046, 24033, "2030/12/17 14:59:59", 8.27);
